"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import {
  LayoutDashboard,
  Package,
  ShoppingCart,
  LogOut,
  X,
  User,
  Settings
} from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { useAuthContext } from "@/components/providers/auth-provider"

interface SidebarProps {
  isOpen: boolean
  onClose: () => void
}

const navigation = [
  { name: "Dashboard", href: "/", icon: LayoutDashboard },
  { name: "Inventory", href: "/inventory", icon: Package },
  { name: "Procurement", href: "/procurement", icon: ShoppingCart },
]

const accountPages = [
  { name: "Profile", href: "/profile", icon: User },
  { name: "Settings", href: "/settings", icon: Settings },
]

export function Sidebar({ isOpen, onClose }: SidebarProps) {
  const pathname = usePathname()
  const { signOut, user } = useAuthContext()

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      {isOpen && (
        <div
          className="fixed inset-0 z-40 bg-vision-navy/80 backdrop-blur-sm md:hidden"
          onClick={onClose}
        />
      )}

      <aside
        className={cn(
          "fixed left-0 top-0 z-40 h-screen w-[280px] transition-transform duration-300 md:translate-x-0 p-4",
          isOpen ? "translate-x-0" : "-translate-x-full"
        )}
      >
        <div className="flex h-full flex-col glass-card rounded-2xl overflow-hidden">
          {/* Logo */}
          <div className="flex items-center gap-3 p-6 pb-4">
            <div className="h-10 w-10 rounded-xl icon-bg-blue flex items-center justify-center text-white font-bold shadow-lg shadow-vision-blue/30">
              P
            </div>
            <span className="font-bold text-lg text-white">Pokemon Resale</span>
            <Button
              variant="ghost"
              size="icon"
              className="ml-auto md:hidden text-white/60 hover:text-white hover:bg-white/10"
              onClick={onClose}
            >
              <X className="h-5 w-5" />
            </Button>
          </div>

          {/* Divider */}
          <div className="mx-6 h-px bg-gradient-to-r from-transparent via-white/20 to-transparent" />

          {/* Main Navigation */}
          <nav className="flex-1 space-y-1 p-4">
            {navigation.map((item) => {
              const isActive = pathname === item.href
              return (
                <Link
                  key={item.name}
                  href={item.href}
                  onClick={() => onClose()}
                  className={cn(
                    "flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-medium transition-all",
                    isActive
                      ? "bg-gradient-to-r from-vision-blue to-vision-cyan text-white shadow-lg shadow-vision-blue/25"
                      : "text-white/60 hover:bg-white/5 hover:text-white"
                  )}
                >
                  <div className={cn(
                    "flex items-center justify-center w-8 h-8 rounded-xl transition-all",
                    isActive
                      ? "bg-white/20"
                      : "bg-vision-navy-light"
                  )}>
                    <item.icon className="h-4 w-4" />
                  </div>
                  <span>{item.name}</span>
                </Link>
              )
            })}

            {/* Account Pages Section */}
            <div className="pt-4">
              <p className="px-4 py-2 text-xs font-semibold text-white/40 uppercase tracking-wider">
                Account Pages
              </p>
              {accountPages.map((item) => {
                const isActive = pathname === item.href
                return (
                  <Link
                    key={item.name}
                    href={item.href}
                    onClick={() => onClose()}
                    className={cn(
                      "flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-medium transition-all",
                      isActive
                        ? "bg-gradient-to-r from-vision-blue to-vision-cyan text-white shadow-lg shadow-vision-blue/25"
                        : "text-white/60 hover:bg-white/5 hover:text-white"
                    )}
                  >
                    <div className={cn(
                      "flex items-center justify-center w-8 h-8 rounded-xl transition-all",
                      isActive
                        ? "bg-white/20"
                        : "bg-vision-navy-light"
                    )}>
                      <item.icon className="h-4 w-4" />
                    </div>
                    <span>{item.name}</span>
                  </Link>
                )
              })}
            </div>
          </nav>

          {/* Help Card */}
          <div className="mx-4 mb-4">
            <div className="rounded-2xl bg-gradient-to-br from-vision-blue to-vision-cyan p-4 text-white">
              <div className="flex items-center justify-center w-10 h-10 rounded-xl bg-white/20 mb-3">
                <Settings className="h-5 w-5" />
              </div>
              <p className="font-semibold mb-1">Need help?</p>
              <p className="text-sm text-white/80 mb-3">Check our documentation</p>
              <Button
                variant="secondary"
                size="sm"
                className="w-full bg-white text-vision-blue hover:bg-white/90 font-semibold"
              >
                Documentation
              </Button>
            </div>
          </div>

          {/* User Section */}
          <div className="border-t border-white/10 p-4 space-y-3">
            {user && (
              <div className="flex items-center gap-3 px-2">
                <div className="w-8 h-8 rounded-xl bg-gradient-to-br from-vision-purple to-vision-pink flex items-center justify-center text-white text-sm font-semibold">
                  {user.email?.charAt(0).toUpperCase()}
                </div>
                <span className="text-sm text-white/60 truncate flex-1">
                  {user.email}
                </span>
              </div>
            )}
            <Button
              variant="ghost"
              className="w-full justify-start gap-3 text-white/60 hover:text-white hover:bg-white/5 rounded-xl"
              onClick={handleSignOut}
            >
              <div className="flex items-center justify-center w-8 h-8 rounded-xl bg-vision-navy-light">
                <LogOut className="h-4 w-4" />
              </div>
              Sign Out
            </Button>
          </div>
        </div>
      </aside>
    </>
  )
}
